// Vereinswappen als base64 (JPEG) für die Grafiken.
// LOGO = Familien-Logo (Team 1 / allgemein), LOGO2 = goldenes "Calcio Strada 2" (Team 2).
const LOGO_B64 = '';
const LOGO_W = 420;
const LOGO_H = 420;
const LOGO2_B64 = '';
const LOGO2_W = 406;
const LOGO2_H = 420;

// Passendes Logo je Teamnummer ("2" -> goldenes Wappen, sonst Familien-Logo)
function getLogo(num) {
  if (String(num) === '2') return { b64: LOGO2_B64, w: LOGO2_W, h: LOGO2_H, mime: 'image/jpeg' };
  return { b64: LOGO_B64, w: LOGO_W, h: LOGO_H, mime: 'image/jpeg' };
}

module.exports = { LOGO_B64, LOGO_W, LOGO_H, LOGO2_B64, LOGO2_W, LOGO2_H, getLogo };
